WITH catalog_agg AS ( SELECT cs.cs_call_center_sk, cs.cs_ship_mode_sk, SUM(cs.cs_ext_sales_price) AS catalog_sales_revenue, SUM(cs.cs_net_profit) AS catalog_net_profit FROM catalog_sales cs GROUP BY cs.cs_call_center_sk, cs.cs_ship_mode_sk ), web_agg AS ( SELECT ws.ws_ship_mode_sk, SUM(ws.ws_ext_sales_price) AS web_sales_revenue, SUM(ws.ws_net_profit) AS web_net_profit FROM web_sales ws GROUP BY ws.ws_ship_mode_sk ) SELECT cc.cc_call_center_id, cc.cc_name, sm.sm_type, ca.catalog_sales_revenue, wa.web_sales_revenue, CASE WHEN ca.catalog_sales_revenue = 0 THEN NULL ELSE wa.web_sales_revenue / ca.catalog_sales_revenue END AS web_to_catalog_rev_ratio, CASE WHEN ca.catalog_net_profit + COALESCE(wa.web_net_profit, 0) > 100000 THEN 'High Profit' WHEN ca.catalog_net_profit + COALESCE(wa.web_net_profit, 0) BETWEEN 50000 AND 100000 THEN 'Medium Profit' ELSE 'Low Profit' END AS profit_category, ROUND(100.0 * (ca.catalog_sales_revenue + COALESCE(wa.web_sales_revenue, 0)) / SUM(ca.catalog_sales_revenue + COALESCE(wa.web_sales_revenue, 0)) OVER (), 2) AS contribution_pct, ROW_NUMBER() OVER (PARTITION BY cc.cc_call_center_sk ORDER BY (ca.catalog_sales_revenue + COALESCE(wa.web_sales_revenue, 0)) DESC) AS revenue_rank_per_center FROM catalog_agg ca JOIN call_center cc ON ca.cs_call_center_sk = cc.cc_call_center_sk JOIN ship_mode sm ON ca.cs_ship_mode_sk = sm.sm_ship_mode_sk LEFT JOIN web_agg wa ON ca.cs_ship_mode_sk = wa.ws_ship_mode_sk WHERE ca.catalog_sales_revenue > 0 ORDER BY cc.cc_call_center_id, revenue_rank_per_center LIMIT 20
